using Eto.Forms;using Rhino.UI;
namespace RhinoContextAssist;
internal sealed class ContextAssistOptionsPage:OptionsDialogPage{readonly ContextAssistSettings s;ContextAssistOptionsControl? c;public ContextAssistOptionsPage(ContextAssistSettings x):base("Context Assist")=>s=x;public override object PageControl=>c??=new(s);public override bool ShowApplyButton=>true;public override bool OnApply(){c?.Apply();return true;}}
internal sealed class ContextAssistOptionsControl:Panel{readonly ContextAssistSettings s;readonly DropDown pos=new(),ux=new(),kind=new();readonly NumericStepper margin=N(50,250),primary=N(1,5);readonly ListBox actions=new(){Height=330};readonly CheckBox enabled=new(){Text="Aktiviert"},auto=new(){Text="Automatisch priorisieren"};
 public ContextAssistOptionsControl(ContextAssistSettings x){s=x;foreach(var t in new[]{"Neben Mauszeiger","Direkt an Geometrie","Mit Abstand zur Geometrie","Automatisch freie Ecke","Links oben","Rechts oben","Links unten","Rechts unten"})pos.Items.Add(t);foreach(var t in new[]{"Direkt","Kompakt","Manuell"})ux.Items.Add(t);foreach(var k in ActionCatalog.Kinds)kind.Items.Add(k.ToString());var favorite=B("Favorit umschalten",130),up=B("Nach oben",95),down=B("Nach unten",95);favorite.Click+=(_,_)=>ToggleFavorite();up.Click+=(_,_)=>Move(-1);down.Click+=(_,_)=>Move(1);kind.SelectedIndexChanged+=(_,_)=>Refresh();var display=new DynamicLayout{Padding=10,Spacing=new Eto.Drawing.Size(6,6)};display.AddRow(enabled,auto);display.AddRow("Darstellung",ux);display.AddRow("Position",pos);display.AddRow("Randabstand",margin);display.AddRow("Hauptaktionen",primary);var a=new DynamicLayout{Padding=10,Spacing=new Eto.Drawing.Size(6,6)};a.AddRow(kind);a.AddRow(actions);a.AddRow(Row(favorite,up,down));var tabs=new TabControl();tabs.Pages.Add(new TabPage{Text="Darstellung",Content=display});tabs.Pages.Add(new TabPage{Text="Aktionen & Favoriten",Content=a});Content=tabs;LoadSettings();}
 static NumericStepper N(double a,double b)=>new(){MinValue=a,MaxValue=b,DecimalPlaces=0};static Button B(string t,int w)=>new(){Text=t,Width=w,Height=30};static StackLayout Row(params Button[] bs){var r=new StackLayout{Orientation=Orientation.Horizontal,Spacing=6};foreach(var b in bs)r.Items.Add(b);return r;}
 void LoadSettings(){enabled.Checked=s.Enabled;auto.Checked=s.AutomaticPrioritization;pos.SelectedIndex=(int)s.PositionMode;ux.SelectedIndex=(int)s.UxMode;margin.Value=s.CornerMarginPx;primary.Value=s.PrimaryCount;kind.SelectedIndex=0;Refresh();}
 void Refresh(){actions.Items.Clear();if(kind.SelectedIndex<0)return;var k=ActionCatalog.Kinds[kind.SelectedIndex];foreach(var a in ActionCatalog.Defaults(k))actions.Items.Add($"{(s.IsFavorite(k,a.Id)?"★":"☆")} {a.Icon} {a.Label} [{a.Category}]");}
 void ToggleFavorite(){if(kind.SelectedIndex<0||actions.SelectedIndex<0)return;var k=ActionCatalog.Kinds[kind.SelectedIndex];var list=ActionCatalog.Defaults(k);if(actions.SelectedIndex<list.Count)s.ToggleFavorite(k,list[actions.SelectedIndex].Id);Refresh();}
 void Move(int d){if(kind.SelectedIndex<0||actions.SelectedIndex<0)return;var k=ActionCatalog.Kinds[kind.SelectedIndex];var p=s.Preferences[k];var i=actions.SelectedIndex,j=i+d;if(j<0||j>=p.Count)return;(p[i],p[j])=(p[j],p[i]);s.Save();Refresh();actions.SelectedIndex=j;}
 public void Apply(){s.Enabled=enabled.Checked==true;s.AutomaticPrioritization=auto.Checked==true;s.PositionMode=(PopupPositionMode)Math.Max(0,pos.SelectedIndex);s.UxMode=(PopupUxMode)Math.Max(0,ux.SelectedIndex);s.CornerMarginPx=(int)margin.Value;s.PrimaryCount=(int)primary.Value;s.Save();}}
